#!/usr/bin/env python3
# apply_tvx_tg.py — TVX_TG_20261008   (requires TVX_V1 → TVX_HILO → TVX_T2)
# ============================================================================
# TV Alerts: paper ENTRY / EXIT / T1-pass messages to the Telegram group, via
# the relay's POST /notify (same bot as the TradingView alerts; the bot token
# stays in Cloudflare; the app authenticates with the READ_TOKEN it already has).
#   * entry: contract, signal + time, fill (ask), SL price/distance, TP (T1/T2 alert),
#     futures, expiry · exit: reason, fill (bid), points, net, held, best/worst,
#     futures for/against, T1 comparison · T1 pass (optional)
#   * durable ordered outbox (tvx_notify), its own sender thread — Telegram can
#     never delay the trading loop; retry 5s→15s→60s→120s→300s; dropped after 30 min
#   * Settings switches + delivery health on the page
#
# Self-contained. RUN ONLY THIS SCRIPT.   Also deploy the updated tv-relay.
#   cd ~/dev/scalp-app && python3 apply_tvx_tg.py [--dry-run] [--allow-dirty]
#
# REPLACES (each must still be the exact TVX_T2 file — sha256-guarded):
#   backend/app/engine/tvx/{tvx_core,tvx_repo,tvx_engine,test_tvx}.py
#   backend/app/api/tvx_routes.py · frontend/src/pages/TvAlerts.jsx · docs/TVX_V1.md
# Mirrors into desktop/src-tauri/{backend,frontend} when present.
# api_server.py and App.jsx are NOT touched.
# ============================================================================

import argparse, base64, hashlib, os, py_compile, shutil, subprocess, sys, tempfile
from pathlib import Path

FENCE = "TVX_TG_20261008"
PARENT = "TVX_T2_20261007"
PAYLOADS = {
    'backend/app/engine/tvx/tvx_core.py': ('',
        '3385e605d99180a313619893192777b16c7cbf250fe82ccb53ce38d2b191b0d1'),
    'backend/app/engine/tvx/tvx_repo.py': ('',
        '8ded7567300b589195be477338b1538aea6bcb42eb9ce26fed4975d760c35c18'),
    'backend/app/engine/tvx/tvx_engine.py': ('',
        'f0b192d956d6037f0c819534f20a08a095eadce325838b47c18e5be22c9e43d9'),
    'backend/app/engine/tvx/test_tvx.py': ('',
        '327b5a5ebe9f5b51af2ed4b357f806f4a0f9b3546ae90068bad7662eb9375e5b'),
    'backend/app/api/tvx_routes.py': ('',
        '459677361656d25b6340bc96590915ddef124387be6b40f1c6af3f7b87ee0164'),
    'frontend/src/pages/TvAlerts.jsx': ('',
        '7b713902a6ce6c71bcb9f9874c52aad8e612631019fdd38adec9bbcac710248c'),
    'docs/TVX_V1.md': ('',
        'b3528f3c4f4768fa1af8b611305cb633b5408e3f2e89143369cabfbb5ca46ea5'),
}
V1_SHA = {
    'backend/app/engine/tvx/tvx_core.py': '96d4ae8d1cca45a94f4d4ccc5599626346c0904e4a9b9800bf589ba1e39c6836',
    'backend/app/engine/tvx/tvx_repo.py': '9aa95dec4fddaa08caaf201c8b1fd44f8fb3b946f12b8923592ac547ed97d763',
    'backend/app/engine/tvx/tvx_engine.py': 'a654440e22abb26878cb2446e37ad03aa0ef08208b5f3101f8f337a35e95a230',
    'backend/app/engine/tvx/test_tvx.py': '6cb134352ed6968097d1df620d51d189bda912f67a152580cf2cbc2a5b9be179',
    'backend/app/api/tvx_routes.py': 'e5b9ec7ad37e93f51ed09b0bda26a663ff424fa45f7b4585845024f74518ffd5',
    'frontend/src/pages/TvAlerts.jsx': '4da51ac5213b773db4674f70fc3101056cfcc6ebee33628b310d77f4691bf7f4',
    'docs/TVX_V1.md': '7482fa7b601c9f33cecacb15472d83179dca8afb49e4875b765216604998f0c8',
}
MIRRORS = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}


def die(msg):
    print(f"\n✖ ABORT: {msg}\nNothing was written.")
    sys.exit(1)


def ok(msg):
    print(f"  ✓ {msg}")


def sha(b):
    return hashlib.sha256(b).hexdigest()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--allow-dirty", action="store_true")
    args = ap.parse_args()
    root = Path.cwd()
    print(f"apply_tvx_tg.py — {FENCE}  (repo: {root})\n")

    # 1. parent + fence
    api = root / "backend/app/api_server.py"
    if not api.is_file():
        die("backend/app/api_server.py not found — run from the scalp-app repo root")
    eng = root / "backend/app/engine/tvx/tvx_engine.py"
    if not eng.is_file() or "TVX_V1_20261007" not in api.read_text():
        die("TVX_V1_20261007 is not applied — run apply_tvx_v1.py, apply_tvx_hilo.py, apply_tvx_t2.py first")
    if "TVX_HILO_20261007" not in eng.read_text():
        die("TVX_HILO_20261007 is not applied — run apply_tvx_hilo.py, then apply_tvx_t2.py first")
    if PARENT not in eng.read_text():
        die(f"{PARENT} is not applied — run apply_tvx_t2.py first")
    if FENCE in eng.read_text():
        die(f"{FENCE} already present — already applied")
    ok(f"parent {PARENT} present, {FENCE} absent")

    # 2. every file to replace is byte-identical to the V1 delivery
    for p, want in V1_SHA.items():
        f = root / p
        if not f.is_file():
            die(f"{p} missing — TVX install incomplete")
        if sha(f.read_bytes()) != want:
            die(f"{p} differs from the TVX_T2 version (edited by hand or another patch). "
                f"Restore it (git checkout / the V1 apply) and re-run")
    ok(f"{len(V1_SHA)} TVX files verified unchanged since TVX_T2 (sha256)")

    # 3. git: an M on a target is a stop sign
    try:
        st = subprocess.run(["git", "status", "--porcelain", "--"] + list(V1_SHA), cwd=root,
                            capture_output=True, text=True, timeout=30).stdout
    except Exception:
        st = ""
    mods = [l for l in st.splitlines() if l[:2].strip().startswith("M")]
    if mods and not args.allow_dirty:
        die("targets have uncommitted modifications:\n" + "\n".join(mods) + "\nCommit first, or --allow-dirty")
    ok("git: no uncommitted edits on targets" if not mods else "dirty targets allowed")

    # 4. payloads
    new = {}
    for p, (b64, h) in PAYLOADS.items():
        data = base64.b64decode(b64)
        if sha(data) != h:
            die(f"payload checksum mismatch for {p}")
        new[p] = data.decode("utf-8")
    ok(f"{len(new)} payloads verified (sha256)")

    # 5. py_compile
    with tempfile.TemporaryDirectory() as td:
        for p, s in new.items():
            if p.endswith(".py"):
                f = Path(td) / p
                f.parent.mkdir(parents=True, exist_ok=True)
                f.write_text(s)
                try:
                    py_compile.compile(str(f), doraise=True)
                except py_compile.PyCompileError as e:
                    die(f"py_compile failed for {p}:\n{e}")
    ok("py_compile: all replaced Python files")

    # 6. full TVX suite (V1 + range) in a scratch copy of backend/
    with tempfile.TemporaryDirectory() as td:
        scratch = Path(td) / "backend"
        shutil.copytree(root / "backend" / "app", scratch / "app",
                        ignore=shutil.ignore_patterns("__pycache__", "*.bak-*", "*.pyc"))
        for p, s in new.items():
            if p.startswith("backend/"):
                (scratch / p[len("backend/"):]).write_text(s)
        r = subprocess.run([sys.executable, "-m", "app.engine.tvx.test_tvx"], cwd=scratch,
                           capture_output=True, text=True, timeout=300)
        if r.returncode != 0:
            print(r.stdout[-6000:], r.stderr[-3000:])
            die("TVX suite failed (output above)")
        ok(f"TVX suite: {r.stdout.count('  PASS  ')} checks passed ({r.stdout.strip().splitlines()[-1]})")

    # 7. esbuild parse
    esb = next((c for c in (root / "frontend/node_modules/.bin/esbuild",
                            root / "desktop/node_modules/.bin/esbuild",
                            root / "desktop/src-tauri/frontend/node_modules/.bin/esbuild") if c.exists()), None) \
        or shutil.which("esbuild")
    if esb:
        with tempfile.TemporaryDirectory() as td:
            f = Path(td) / "TvAlerts.jsx"
            f.write_text(new["frontend/src/pages/TvAlerts.jsx"])
            r = subprocess.run([str(esb), str(f), "--loader:.jsx=jsx", "--jsx=automatic", "--log-level=error"],
                               capture_output=True, text=True, timeout=60)
            if r.returncode != 0:
                die(f"esbuild could not parse TvAlerts.jsx:\n{r.stderr[-2000:]}")
        ok(f"esbuild parsed TvAlerts.jsx ({esb})")
    else:
        print("  ! esbuild not found — JSX parse skipped (build-scalp.sh will compile it)")

    # 8. plan
    plan = []
    for p, s in new.items():
        plan.append(root / p)
        for src, dst in MIRRORS.items():
            if p.startswith(src) and (root / dst).is_dir():
                plan.append(root / (dst + p[len(src):]))
    content = {}
    for f in plan:
        rel = str(f.relative_to(root))
        for src, dst in MIRRORS.items():
            if rel.startswith(dst):
                rel = src + rel[len(dst):]
        content[f] = new[rel]
    if args.dry_run:
        print("\nDRY RUN — would replace:")
        for f in plan:
            print(f"    {f.relative_to(root)}")
        print("\nAll gates passed. Re-run without --dry-run to apply.")
        return

    # 9. staged all-or-nothing
    done = []
    try:
        for f in plan:
            if f.exists():
                bak = f.with_name(f.name + f".bak-{FENCE}")
                shutil.copy2(f, bak)
                done.append((f, bak))
            else:
                done.append((f, None))
            f.parent.mkdir(parents=True, exist_ok=True)
            tmp = f.with_name(f.name + ".tg-tmp")
            tmp.write_text(content[f])
            os.replace(tmp, f)
    except Exception as e:
        for f, bak in reversed(done):
            if bak:
                shutil.copy2(bak, f)
                bak.unlink(missing_ok=True)
            else:
                f.unlink(missing_ok=True)
        die(f"write failed ({e}) — rolled back")

    print("\nReplaced:")
    for f, _ in done:
        print(f"    {f.relative_to(root)}")
    print(f"""
✔ {FENCE} applied.

Next:
  1. git add backend/app/engine/tvx backend/app/api/tvx_routes.py frontend/src/pages/TvAlerts.jsx docs/TVX_V1.md
     git commit -m "{FENCE}: TV Alerts entry/exit messages to Telegram"
  2. Deploy the updated tv-relay (adds POST /notify):  cd ~/dev/tv-relay && npm test && wrangler deploy
  3. ./desktop/build-scalp.sh both
  Messages are ON by default (TV Alerts → Settings). Until the relay is
  redeployed they fail with "relay HTTP 404", are retried, and are dropped
  after 30 minutes — trading is never affected.
""")


if __name__ == "__main__":
    main()
